#!/usr/bin/env python3
"""Write redo/steps/pr45-term.json: the recorded proof of PR 45 (sim: drp_gpu) at its head."""
import json, os, sys
RUN = sys.argv[1] if len(sys.argv) > 1 else 'take1'
BASE = '5b1f5587d'
GPU_FAULT = 'DrpTDet.PcieControl.DevPcie.TDetSemi.Length_0'
steps = []
def s(send, expect=None, timeout=None):
    d = {'send': send}
    if expect: d['expect'] = expect
    if timeout: d['timeout'] = timeout
    steps.append(d)
C = ' | cut -c1-138'
s('date -Is; hostname   # this machine: the exe.dev VM')
s('ssh -t sdfiana025 bash --rcfile $R/logs/proof45/rc.sh -i', expect=r'cwang31@sdfiana025', timeout=180)
s("hostname; date '+%F %T %Z'; echo \"S=$S\"; echo \"SG=$SG\"")
s('# every node command below is its own Slurm step on sdfada013 ($S; $SG also holds the node\'s GPU); each DAQ up..down holds the node lock')
s('git fetch -q origin && git merge origin/agentify; git rev-parse HEAD; git log -1 --format=\'%s\'' + C + '; echo "local changes: $(git status --short --untracked-files=no | wc -l)"', timeout=180)
s(f"git log --format='%h %s' {BASE}..HEAD" + C)
s(f"git diff --stat {BASE} HEAD | tail -1; git diff --stat=138 {BASE} HEAD -- psdaq/drp psdaq/drpGpu psana" + C)
s('# The node has no CUDA toolkit; the builds use conda-forge\'s 12.9 and 13.3, installed in the project\'s scratch (a GPU step, for nvidia-smi)')
s('$SG bash $L/toolkit.sh', expect=r"include/cccl \(the toolkit's own\)", timeout=300)
s('# GreenCtxCompat.hh (1cd736f07), preprocessed under each toolkit: with CUDA 12.9 it maps the green contexts onto the driver API; with 13.3 it adds nothing')
s('$S bash $L/compat.sh', expect=r'cuda-13\.3: GreenCtxCompat', timeout=300)
s(f"export P=$L/{RUN}; mkdir -p $P/ev; echo \"records in $P/ev: $(ls -A $P/ev | wc -l); work dirs in $P: $(ls -d $P/wd-* 2>/dev/null | wc -l)\"")
s('# Build at this HEAD, fresh (build_all.sh -f -d): CUDA 12.9 here (the runs below use it), then CUDA 13.3 in wt-gpu-cuda13 at the same HEAD')
s('$S bash $L/build.sh wt-gpu 12.9', expect=r'^BUILD_EXIT=\d+[\s\S]*GPU libs', timeout=2400)
s("git -C $R/wt-gpu-cuda13 rev-parse --short HEAD; echo \"wt-gpu-cuda13 local changes: $(git -C $R/wt-gpu-cuda13 status --short --untracked-files=no | wc -l)\"")
s('$S bash $L/build.sh wt-gpu-cuda13 13.3', expect=r'^BUILD_EXIT=\d+[\s\S]*GPU libs', timeout=2400)
s('# CUDA 13.3 compiles only: this node\'s driver (575) runs CUDA 12.9 at most, so every run below uses the 12.9 build')
s(f'# At the base {BASE} (worktree wt-nb45) drpGpu does not configure on this node with either toolkit: its meson.build hard-codes /usr/local/cuda')
s("git -C $R/wt-nb45 log -1 --format='wt-nb45 %h %s'" + C + "; echo \"wt-nb45 local changes: $(git -C $R/wt-nb45 status --short --untracked-files=no | wc -l)\"")
s('for v in 12.9 13.3; do $S bash $L/basemeson.sh wt-nb45 $v; done', expect=r'meson setup \(CUDA 13\.3\)[\s\S]*SETUP_EXIT=\d+[\s\S]*ERROR', timeout=600)
s('# The CI (Test DAQ) builds with ./build_all.sh -d and no nvcc, so meson skips psdaq/drpGpu; the same fresh build at base (wt-nb45) and at this HEAD (wt-nh45)')
s("grep -n 'build_all' .github/workflows/run_daq_tests.yaml" + C + "; git -C $R/wt-nh45 rev-parse --short HEAD")
s('$S bash $L/build.sh wt-nb45 none', expect=r'^BUILD_EXIT=\d+[\s\S]*GPU libs', timeout=2400)
s('$S bash $L/build.sh wt-nh45 none', expect=r'^BUILD_EXIT=\d+[\s\S]*GPU libs', timeout=2400)
s('$S bash $L/nocuda.sh wt-nb45 wt-nh45', expect=r'COMMANDS_DIFF_EXIT=\d+', timeout=600)
s(f"grep -n -E '^if |^endif' psdaq/drpGpu/meson.build; git diff -U0 {BASE} HEAD -- psdaq/drpGpu/meson.build | grep '^@@'; git diff --stat {BASE} HEAD -- '*meson.build' meson_options.txt build_all.sh")
s('# The sim unit tests at this HEAD (one step, node lock)')
s('$S bash $L/pytest.sh', expect=r'PYTEST_EXIT=\d+', timeout=1800)
s('# Each GPU type on a fresh simulated DAQ in one GPU step: up --det <type> --drp drp_gpu, cycle --events 1000, down; its drp_gpu log;')
s('# xtc2_check --drp drp_gpu on the file (every pixel of every event: as written must PASS, --self-test-offset 1 must FAIL)')
s('# fakecam: Gpu::AreaDetector, configured by xpmdet_config as drp -D fakecam is; then a fault run: TDetSemi.Length_0 reads back wrong')
s(f'$SG bash $L/gpurun.sh fakecam $P {GPU_FAULT}', expect=r'GPURUN_DONE fakecam', timeout=2400)
s('# epixuhremu: Gpu::EpixUHRemu, configured by epixuhremu_configTiming and xpmdet_config; the same fault run')
s(f'$SG bash $L/gpurun.sh epixuhremu $P {GPU_FAULT}', expect=r'GPURUN_DONE epixuhremu', timeout=2400)
s('# epixuhrsim: Gpu::EpixUHRsim, its SimDetector\'s 16 frames timed by simxpm; checked against the frames and constants it writes (sim_ref)')
s('$SG bash $L/gpurun.sh epixuhrsim $P', expect=r'GPURUN_DONE epixuhrsim', timeout=2400)
s('# 695b1b2ee (AreaDetector: pedestals 0 and gains 1, not null pointers): the same command at a base without it and at this HEAD.')
s('# Base: wt-gpu-r695 = this HEAD with 695b1b2ee reverted (4bde760d1, detached, not on any branch), built with CUDA 12.9 before the recording')
s("git -C $R/wt-gpu-r695 log -2 --format='%h %s'" + C + "; git -C $R/wt-gpu-r695 diff --stat HEAD~1 HEAD | tail -1; echo \"local changes: $(git -C $R/wt-gpu-r695 status --short --untracked-files=no | wc -l)\"")
s("grep -E '^build|^nvcc on|^BUILD_EXIT' $L/prebuild.log | grep -A2 wt-gpu-r695 | sed \"s#$R#\\$R#g\"" + C + "; ninja -C $R/wt-gpu-r695/builddir -n | tail -1")
s('for w in wt-gpu-r695 wt-gpu; do $SG bash $L/fix695.sh $w $P; done', expect=r'FIX695_DONE wt-gpu \d', timeout=2400)
s('# The CPU DRP\'s 14 types of PRs #34, #36 and #39 at this HEAD (XpmDetector and BEBDetector now reach MemPoolSim through MemPool::sim()):')
s('# one step, each type on a fresh DAQ under the node lock: up --det <type>, cycle --events 1000, down, then xtc2_check as written and with the offset')
s('$S bash $L/cputypes.sh $P opal piranha4 tb epixquad fakecam cspad epixhremu jungfrauemu ts hrencoder epixm320 epix100 wave8 wave8he',
  expect=r'CPUTYPES_DONE', timeout=5400)
s('# daq_sim coverage at this HEAD over the 17 records (3 drp_gpu, 14 drp)')
s('$S bash $L/cov.sh $P', expect=r'lines in cov\.txt', timeout=1800)
s("grep -E '^det:drp_gpu:|^prog:(control|drp|drp_gpu|teb|pyxpm) ' $P/cov.txt" + C)
s("echo \"det rows RUN: $(grep -cE '^det:[a-z_]+:[A-Za-z0-9]+ +RUN +evidence' $P/cov.txt)\"; grep -E '^[0-9]+ rows|^status file|^(PASS|FAIL)' $P/cov.txt" + C)
s('# Negatives: (1) the drp_gpu fakecam record left out, the CPU drp\'s fakecam record kept: det:drp_gpu:fakecam must drop;')
s('# (2) also a copy of that drp record with its rows renamed to det:drp_gpu:fakecam and prog:drp_gpu: a drp record must not prove a drp_gpu row')
s('$S bash $L/neg.sh $P', expect=r'COVERAGE_EXIT=\d+ \(forged\)', timeout=2400)
s("for t in no-gpu-fakecam forged; do echo \"== cov-$t.txt\"; grep -E '^det:drp(_gpu)?:fakecam |^[0-9]+ rows|^(PASS|FAIL)|^  det:' $P/cov-$t.txt | sed \"s#$P/##g\" | fold -w 138; done")
s('# The hardware path (no sim:// device) of what this PR changes, from base and head builds, the same commands (hwpath.sh), GPU step, node lock.')
s('# (a) drp_gpu and drp from the CUDA 12.9 builds of 1cd736f07 (wt-gpu-base: this PR\'s first commit, the oldest drpGpu that builds here) and this HEAD')
s("git -C $R/wt-gpu-base log -1 --format='wt-gpu-base %h %s'" + C + "; echo \"local changes: $(git -C $R/wt-gpu-base status --short --untracked-files=no | wc -l)\"; ninja -C $R/wt-gpu-base/builddir -n | tail -1")
s('$SG bash $L/hwrun.sh $P wt-gpu-base wt-gpu cuda', expect=r'HWPATH_DIFF_EXIT=\d+', timeout=1200)
s("grep -E '^-- |^rc=' $P/hw-wt-gpu.log" + C)
s("grep -A9 -E '^-- drp_gpu .*epixuhrsim' $P/hw-wt-gpu.log | grep -E 'Built with|SM resources|Ready|rc='" + C)
s(f'# (b) drp and psana from the no-CUDA builds (as CI builds) of base {BASE} (wt-nb45) and this HEAD (wt-nh45)')
s('$S bash $L/hwrun.sh $P wt-nb45 wt-nh45 nocuda', expect=r'HWPATH_DIFF_EXIT=\d+', timeout=1200)
s("cat $P/hw-diff-nocuda.txt" + C + "; grep -E '^-- |^rc=|^(fakecam|epixhremu|epix100): ' $P/hw-wt-nh45.log" + C)
s("echo \"local changes: $(git status --short --untracked-files=no | wc -l)\"; git rev-parse HEAD; date '+%F %T %Z'")
s('exit', expect=r'exedev@', timeout=60)
out = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'steps', 'pr45-term.json')
json.dump(steps, open(out, 'w'), indent=1)
print(f'{len(steps)} steps -> {os.path.normpath(out)}')
